install(Authentication) {
    basic("auth-basic") {
        validate { credentials: UserPasswordCredential ->
            users.verify(credentials.name, credentials.password)?.let { UserPrincipal(it.id) }
        }
    }
    bearer("auth-bearer") {
        authenticate { token -> tokens.verify(token.token)?.let { UserPrincipal(it.id) } }
    }
}
routing {
    authenticate("auth-basic") {
        get("/orders") {
            val principal = call.principal<UserPrincipal>()!!
            call.respond(orders(principal.id))
        }
    }
}
